function getAbnormalSecurityTranslation(key, lang) {
    return (abnormalsecurityTranslations[lang] && abnormalsecurityTranslations[lang][key]) ||
           (abnormalsecurityTranslations.en && abnormalsecurityTranslations.en[key]) || null;
}

function applyAbnormalSecurityTranslations(lang) {
    let count = 0;
    document.querySelectorAll("[data-i18n]").forEach(el => {
        const key = el.getAttribute("data-i18n");
        if (key && (key.startsWith("review.abnormal-security.") || key.startsWith("review.common."))) {
            const translation = getAbnormalSecurityTranslation(key, lang);
            if (translation) { el.textContent = translation; count++; }
        }
    });
    
}

window.addEventListener("languageChanged", e => setTimeout(() => applyAbnormalSecurityTranslations(e.detail.language), 200));

if (document.readyState === "loading") {
    document.addEventListener("DOMContentLoaded", () => applyAbnormalSecurityTranslations(window.i18n?.getCurrentLanguage() || "en"));
} else {
    applyAbnormalSecurityTranslations(window.i18n?.getCurrentLanguage() || "en");
}
